from jsonb_to_recordset($json$[{"id":"che-pe-137","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Group 1 elements other than hydrogen are collectively called","options":["alkaline earth metals","alkali metals","chalcogens","pnictogens"],"answer_index":1,"explanation":"Li, Na, K, Rb, Cs and Fr are the alkali metals.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-138","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Beryllium, magnesium, calcium, strontium, barium and radium are the","options":["alkali metals","alkaline earth metals","halogens","coinage metals"],"answer_index":1,"explanation":"They form group 2 and have the valence configuration ns².","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-139","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine, chlorine, bromine, iodine and astatine belong to the","options":["noble-gas family","halogen family","alkali-metal family","coinage-metal family"],"answer_index":1,"explanation":"Group 17 elements are the halogens (salt-formers).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-140","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Neon, argon, krypton, xenon and radon occupy the","options":["first vertical column","last vertical column of the long form table","f-block","middle of the d-block"],"answer_index":1,"explanation":"They are the noble gases of group 18 (helium is also placed there).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-141","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Main-group (representative) elements are those belonging to the","options":["d-block only","s- and p-blocks","f-block only","inner transition series"],"answer_index":1,"explanation":"s- and p-block elements have their last electron in an ns or np orbital and show the classic group valences.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-142","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"An element is classed as a transition metal if it has an incomplete d subshell in the","options":["nucleus","free atom or in any of its common ions","noble-gas core only","f subshell exclusively"],"answer_index":1,"explanation":"IUPAC uses the incomplete-(n−1)d criterion; Zn²⁺ (d¹⁰) is often set aside as a typical transition ion.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-143","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Inner transition metals are distinguished from the d-block by the filling of an","options":["ns subshell","np subshell","f subshell","1s subshell"],"answer_index":2,"explanation":"Lanthanoids fill 4f and actinoids fill 5f, so they are the f-block (inner transition) series.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-144","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Including the fourteen lanthanoids, the sixth period contains","options":["eight elements","eighteen elements","thirty-two elements","ten elements"],"answer_index":2,"explanation":"Period 6 fills 6s, 4f, 5d and 6p: 2 + 14 + 10 + 6 = 32.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-145","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Boron heads group 13; the remaining members of that group are best described as","options":["noble gases","metals","halogens","actinoids"],"answer_index":1,"explanation":"Al, Ga, In and Tl are metals; boron is the non-metallic/metalloid head of the group.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-146","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Helium is placed with the noble gases even though its configuration is $1s^{2}$ because","options":["it has an incomplete p subshell","it has a closed shell and is chemically inert","it is an alkali metal","its atomic number is eighteen"],"answer_index":1,"explanation":"A filled 1s shell gives helium the noble-gas chemistry of group 18, not the s-block reactivity of group 2.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-147","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The fourth period contains eighteen elements because the subshells that fill in that period are","options":["4s and 4p only","4s, 3d and 4p","5s, 4d and 5p","4f and 5d only"],"answer_index":1,"explanation":"Capacity 2 + 10 + 6 = 18; 4f is not occupied until period 6.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-148","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The f-block is printed below the main table because inserting the fourteen lanthanoids into period 6 would","options":["violate the modern periodic law","make that row awkwardly wide","change their atomic numbers","turn them into s-block metals"],"answer_index":1,"explanation":"The two-row footnote is a display convention; chemically the lanthanoids still belong in period 6.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"periods-groups-blocks","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
